import java.io.File;
import java.nio.file.*;
import javax.servlet.http.*;

public class AvatarStore extends HttpServlet {
  private static final Path BASE = Paths.get("/var/avatars").toAbsolutePath().normalize();
  protected File resolve(HttpServletRequest req) {
    String name = req.getParameter("file");
    Path p = BASE.resolve(name).normalize();
    if (!p.startsWith(BASE)) throw new SecurityException("caminho invalido");
    return p.toFile();
  }
}

